def transform(grid):
    from collections import deque
    R, C = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter()
    for row in grid:
        cnt.update(row)
    bg = cnt.most_common(1)[0][0]
    seen = [[False]*C for _ in range(R)]
    out = [row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == bg and not seen[r][c]:
                q = deque([(r, c)])
                seen[r][c] = True
                comp = [(r, c)]
                enclosed = True
                while q:
                    x, y = q.popleft()
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if not (0 <= nx < R and 0 <= ny < C):
                            enclosed = False
                            continue
                        if grid[nx][ny] == bg and not seen[nx][ny]:
                            seen[nx][ny] = True
                            q.append((nx, ny))
                            comp.append((nx, ny))
                if enclosed:
                    for x, y in comp:
                        out[x][y] = 4
    return out
